changeSet.sql:
UPDATE access_requests 
SET accessor_approver_status = 'REQUESTED' 
WHERE accessor_approver_status = 'PENDING';

UPDATE access_requests 
SET asset_approver_status = 'REQUESTED' 
WHERE asset_approver_status = 'PENDING';

UPDATE access_requests 
SET accessor_approver_status = 'RELINQUISHED_BEFORE_APPROVAL' 
WHERE accessor_approver_status = 'CANCELLED';

UPDATE access_requests 
SET asset_approver_status = 'RELINQUISHED_BEFORE_APPROVAL' 
WHERE asset_approver_status = 'CANCELLED';

UPDATE asset_query_change_requests 
SET approval_status = 'REQUESTED' 
WHERE approval_status = 'PENDING';

UPDATE asset_query_change_requests 
SET approval_status = 'RELINQUISHED_BEFORE_APPROVAL' 
WHERE approval_status = 'CANCELLED';

ALTER TABLE asset_credentials 
MODIFY COLUMN user_access_type varchar(50) 
COMMENT 'Type of user access: Admin, Accessor, Asset Owner, Approver, Auditor, User';

ALTER TABLE notification_task 
MODIFY COLUMN email_type varchar(50) 
COMMENT 'Type of email notification: INVITATION, RELINQUISH_ASSET_CREDENTIAL, ASSET_APPROVE_NOTIFY, ACCESSOR_ASSET_REQUEST_NOTIFY, OTHER';

ALTER TABLE notification_task 
MODIFY COLUMN is_sent boolean 
COMMENT 'Flag to indicate if the notification has been sent';

UPDATE access_requests 
SET expiry_date = DATE_ADD(request_time, INTERVAL expiry_hours HOUR)
WHERE expiry_date IS NULL;

ALTER TABLE users CONVERT TO CHARACTER SET utf8 COLLATE utf8_unicode_ci;
ALTER TABLE users 
MODIFY COLUMN email VARCHAR(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
MODIFY COLUMN first_name VARCHAR(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
MODIFY COLUMN last_name VARCHAR(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

ALTER TABLE roles CONVERT TO CHARACTER SET utf8 COLLATE utf8_unicode_ci;
ALTER TABLE roles 
MODIFY COLUMN name VARCHAR(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

ALTER TABLE emails CONVERT TO CHARACTER SET utf8 COLLATE utf8_unicode_ci;
ALTER TABLE emails 
MODIFY COLUMN email_to VARCHAR(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
MODIFY COLUMN subject TEXT CHARACTER SET utf8 COLLATE utf8_unicode_ci;

ALTER TABLE assets CONVERT TO CHARACTER SET utf8 COLLATE utf8_unicode_ci;
ALTER TABLE assets 
MODIFY COLUMN name VARCHAR(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci,
MODIFY COLUMN description TEXT CHARACTER SET utf8 COLLATE utf8_unicode_ci,
MODIFY COLUMN host_address VARCHAR(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci;

ALTER TABLE access_requests CONVERT TO CHARACTER SET utf8 COLLATE utf8_unicode_ci;
ALTER TABLE access_requests 
MODIFY COLUMN access_sql TEXT CHARACTER SET utf8 COLLATE utf8_unicode_ci,
MODIFY COLUMN request_reason TEXT CHARACTER SET utf8 COLLATE utf8_unicode_ci;

-- Check if column exists and drop it if it does
SET @column_exists = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS 
                    WHERE TABLE_SCHEMA = DATABASE() 
                    AND TABLE_NAME = 'licenses' 
                    AND COLUMN_NAME = 'license_file');

SET @sql = IF(@column_exists > 0, 'ALTER TABLE licenses DROP COLUMN license_file', 'SELECT "Column does not exist" AS result');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- Add the column with proper LONGBLOB type
ALTER TABLE licenses ADD COLUMN license_file LONGBLOB;

-- Make it NOT NULL after adding
ALTER TABLE licenses MODIFY COLUMN license_file LONGBLOB NOT NULL;

-- Disable foreign key checks
SET FOREIGN_KEY_CHECKS = 0;

-- Check if foreign key constraint exists and drop it
SET @constraint_exists = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE 
                        WHERE TABLE_SCHEMA = DATABASE() 
                        AND TABLE_NAME = 'notification_task' 
                        AND CONSTRAINT_NAME = 'fk_notification_task_requestor');

SET @sql = IF(@constraint_exists > 0, 
             'ALTER TABLE notification_task DROP FOREIGN KEY fk_notification_task_requestor', 
             'SELECT "Foreign key does not exist" AS result');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- Rename requestor_id to sender_id in notification_task table
ALTER TABLE notification_task CHANGE COLUMN requestor_id sender_id BIGINT;

-- Add the new foreign key constraint
ALTER TABLE notification_task 
ADD CONSTRAINT fk_notification_task_sender 
FOREIGN KEY (sender_id) REFERENCES users(id);

-- Re-enable foreign key checks
SET FOREIGN_KEY_CHECKS = 1;

-- Disable foreign key checks
SET FOREIGN_KEY_CHECKS = 0;

-- Drop existing foreign key constraints if they exist
SET @constraint_exists = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE 
                        WHERE TABLE_SCHEMA = DATABASE() 
                        AND TABLE_NAME = 'notification_task' 
                        AND CONSTRAINT_NAME = 'fk_notification_task_receiver');
SET @sql = IF(@constraint_exists > 0, 
             'ALTER TABLE notification_task DROP FOREIGN KEY fk_notification_task_receiver', 
             'SELECT "fk_notification_task_receiver does not exist" AS result');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @constraint_exists = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE 
                        WHERE TABLE_SCHEMA = DATABASE() 
                        AND TABLE_NAME = 'notification_task' 
                        AND CONSTRAINT_NAME = 'fk_notification_task_sender');
SET @sql = IF(@constraint_exists > 0, 
             'ALTER TABLE notification_task DROP FOREIGN KEY fk_notification_task_sender', 
             'SELECT "fk_notification_task_sender does not exist" AS result');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

